    if not marker:
        return [row[:] for row in grid]

    # Its center is the cell whose color differs from the repeated target color.
    center = next((r for r, v in marker
                   if sum(1 for _, x in marker if x == v) == 1),
                  marker[len(marker) // 2][0])
    pattern = [(r - center, v) for r, v in marker]

    target = next((v for row in grid for v in row
                   if v != bg and all(v != x for _, x in marker)), None)
    # In these puzzles the target is the non-background color other than
    # the marker's colors; use the scattered color if it is present.
    if target is None:
        target = 8

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == target:
                for dr, v in pattern:
                    rr = r + dr
                    if 0 <= rr < h:
                        out[rr][c] = v
    return out
