def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    # Find the contiguous colored marker in the second column.
    marker = [(r, grid[r][1]) for r in range(h) if grid[r][1] != bg]
    if not marker:
        return out
    center = (marker[0][0] + marker[-1][0]) // 2
    pattern = [(r - center, color) for r, color in marker]

    # The scattered object color is distinct from both background and marker.
    marker_colors = {color for _, color in marker}
    target = next((v for v in range(10)
                   if v != bg and v not in marker_colors
                   and any(v in row for row in grid)), None)
    if target is None:
        return out

    for r in range(h):
        for c in range(w):
            if grid[r][c] == target:
                for dr, color in pattern:
                    rr = r + dr
                    if 0 <= rr < h:
                        out[rr][c] = color
    return out
